Step 3 — SAS Code: Building the ML Model​
/* Split data into Training set (to build model) and Testing set (to validate it) */
 data training testing; set 
model_data
; if 
fyear
 <= 2020 then output training; 
/* Use older data to train */
 else output testing; 
/* Reserve recent data for testing */
 run; 
/* Use PROC GLMSELECT to train the model with LASSO */

/* This procedure automatically selects the most important variables */
 proc 
glmselect
 data=training; model 
FutureReturn
 = BM ROE AG SIZE MOM / 
/* List of X variables */
 selection=lar (choose=
sbc
) 
stb
; 
/* Use LASSO to avoid overfitting */
 output out=
model_out
 p=
PredictedReturn
; 
/* Save the model's predictions */
 store 
work.forecast_model
; 
/* Save the model to disk */
 run;
