Step 4 — Making the Forecast for 2026​
/* Create a dataset with Company XYZ's latest financials (2025) */
 data xyz_2025; input BM ROE AG SIZE MOM; 
datalines
; 0.85 0.15 0.05 23.1 0.10 ; 
/* These are XYZ's actual 2025 financial ratios */
 run; 
/* Use the PROCPLM to score (predict for) the new data */
 proc 
plm
 restore=
work.forecast_model
; 
/* Load the trained model */
 score data=xyz_2025 out=
xyz_scored
 predicted=PredReturn2026; 
/* Make prediction! */
 run; 
/* Calculate the predicted 2026 price */
 data 
final_forecast
; set 
xyz_scored
; CurrentPrice2025 = 150; 
/* Assume current price is $150 */
 PredictedPrice2026 = CurrentPrice2025 * (1 + PredReturn2026); run; 
/* Print the result */
 proc print data=
final_forecast
; var CurrentPrice2025 PredReturn2026 PredictedPrice2026; run;
